//! Edge-case integration tests for scale-stat — generated by bug-hunter agent.
//!
//! Note: ferrum-core is a `cdylib`-only crate; its internal scale and transform
//! math lives in `pub(crate)` modules and cannot be imported by integration
//! tests directly. These tests exercise the public `ferrum_scene` types that
//! the scale/stat pipeline produces as output, validating structural contracts
//! of the scene graph emitted by the rendering pipeline.

#[cfg(test)]
mod tests {
    use ferrum_scene::{
        BlendMode, Color, CoordKind, FillStroke, MarkBatch, MarkBatchKind,
        Panel, PathCmd, Rect, SceneGraph, SceneNode,
    };

    fn default_fill_stroke() -> FillStroke {
        FillStroke {
            fill: Some(Color::rgb(70, 130, 180)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        }
    }

    fn make_panel(marks: Vec<MarkBatch>) -> Panel {
        Panel {
            id: 0,
            plot_area: Rect { x: 50.0, y: 10.0, w: 500.0, h: 350.0 },
            clip: Rect { x: 50.0, y: 10.0, w: 500.0, h: 350.0 },
            coord: CoordKind::Cartesian {
                x_domain: Some((0.0, 10.0)),
                y_domain: Some((0.0, 10.0)),
                expand: true,
                clip: true,
            },
            grid: vec![],
            marks,
            axes: vec![],
            annotations: vec![],
            strip_title: vec![],
        }
    }

    // ── SceneGraph structural contracts ────────────────────────────────────

    /// SceneGraph with zero panels must serialize and deserialize without error.
    #[test]
    fn scene_graph_empty_panels_round_trips() {
        let scene = SceneGraph {
            width: 600.0,
            height: 400.0,
            background: Some(Color::rgb(255, 255, 255)),
            title: vec![],
            legend: vec![],
            panels: vec![],
            decorations: vec![],
            selections: vec![],
            interaction: Default::default(),
            chart_description: None,
        };
        let json = serde_json::to_string(&scene).expect("serialize");
        let back: SceneGraph = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(scene, back);
        assert_eq!(back.panels.len(), 0);
    }

    /// SceneGraph width and height survive round-trip exactly (not truncated).
    #[test]
    fn scene_graph_viewport_round_trips_exactly() {
        let scene = SceneGraph {
            width: 1234.567,
            height: 890.123,
            background: None,
            title: vec![],
            legend: vec![],
            panels: vec![],
            decorations: vec![],
            selections: vec![],
            interaction: Default::default(),
            chart_description: None,
        };
        let json = serde_json::to_string(&scene).expect("serialize");
        let back: SceneGraph = serde_json::from_str(&json).expect("deserialize");
        assert!((back.width - 1234.567).abs() < 1e-9, "width lost precision");
        assert!((back.height - 890.123).abs() < 1e-9, "height lost precision");
    }

    /// Circle nodes in a MarkBatch must round-trip with exact cx/cy/r values.
    #[test]
    fn circle_node_coordinates_survive_round_trip() {
        let node = SceneNode::Circle {
            cx: 123.456,
            cy: 789.012,
            r: 4.5,
            style: default_fill_stroke(),
        };
        let batch = MarkBatch {
            kind: MarkBatchKind::Point,
            nodes: vec![node.clone()],
            data_indices: Some(vec![0]),
            tooltips: None,
            hrefs: None,
            descriptions: None,
            keys: None,
            blend: BlendMode::Normal,
            stroke_cap: None,
            stroke_join: None,
        };
        let panel = make_panel(vec![batch]);
        let json = serde_json::to_string(&panel).expect("serialize");
        let back: Panel = serde_json::from_str(&json).expect("deserialize");
        let recovered_node = &back.marks[0].nodes[0];
        match recovered_node {
            SceneNode::Circle { cx, cy, r, .. } => {
                assert!((cx - 123.456).abs() < 1e-9, "cx lost precision: {cx}");
                assert!((cy - 789.012).abs() < 1e-9, "cy lost precision: {cy}");
                assert!((r - 4.5).abs() < 1e-9, "r lost precision: {r}");
            }
            other => panic!("expected Circle, got {other:?}"),
        }
    }

    /// Rect nodes must survive coordinate round-trip (used for bar marks).
    #[test]
    fn rect_node_coordinates_survive_round_trip() {
        let node = SceneNode::Rect {
            x: 50.0,
            y: 100.0,
            w: 80.0,
            h: 200.0,
            style: default_fill_stroke(),
            corner_radius: 2.5,
        };
        let json = serde_json::to_string(&node).expect("serialize");
        let back: SceneNode = serde_json::from_str(&json).expect("deserialize");
        match back {
            SceneNode::Rect { x, y, w, h, corner_radius, .. } => {
                assert!((x - 50.0).abs() < 1e-12);
                assert!((y - 100.0).abs() < 1e-12);
                assert!((w - 80.0).abs() < 1e-12);
                assert!((h - 200.0).abs() < 1e-12);
                assert!((corner_radius - 2.5).abs() < 1e-12);
            }
            other => panic!("expected Rect, got {other:?}"),
        }
    }

    /// Path nodes with NaN coordinates would corrupt SVG path data — the
    /// scene type itself doesn't validate, but a compliant renderer must
    /// never emit NaN. Pin the contract by verifying a finite path round-trips.
    #[test]
    fn path_node_finite_coordinates_survive_round_trip() {
        let node = SceneNode::Path {
            commands: vec![
                PathCmd::MoveTo { x: 0.0, y: 0.0 },
                PathCmd::LineTo { x: 100.0, y: 50.0 },
                PathCmd::Close,
            ],
            style: default_fill_stroke(),
            closed: true,
        };
        let json = serde_json::to_string(&node).expect("serialize path");
        let back: SceneNode = serde_json::from_str(&json).expect("deserialize path");
        match &back {
            SceneNode::Path { commands, .. } => {
                for cmd in commands {
                    match cmd {
                        PathCmd::MoveTo { x, y } | PathCmd::LineTo { x, y } => {
                            assert!(x.is_finite(), "path x is not finite: {x}");
                            assert!(y.is_finite(), "path y is not finite: {y}");
                        }
                        PathCmd::Close => {}
                        _ => {}
                    }
                }
            }
            other => panic!("expected Path, got {other:?}"),
        }
    }

    /// CoordKind::Cartesian with degenerate domain (lo == hi) must serialize
    /// and deserialize without error.
    #[test]
    fn cartesian_coord_degenerate_domain_round_trips() {
        // A degenerate domain [5.0, 5.0] is the problematic case seen with
        // single-row or all-equal data. Verify the scene type survives it.
        let coord = CoordKind::Cartesian {
            x_domain: Some((5.0, 5.0)),
            y_domain: Some((3.0, 3.0)),
            expand: true,
            clip: true,
        };
        let json = serde_json::to_string(&coord).expect("serialize");
        let back: CoordKind = serde_json::from_str(&json).expect("deserialize");
        match back {
            CoordKind::Cartesian { x_domain, y_domain, .. } => {
                let (x_lo, x_hi) = x_domain.expect("x_domain present");
                let (y_lo, y_hi) = y_domain.expect("y_domain present");
                assert!((x_lo - 5.0).abs() < 1e-12 && (x_hi - 5.0).abs() < 1e-12);
                assert!((y_lo - 3.0).abs() < 1e-12 && (y_hi - 3.0).abs() < 1e-12);
            }
            other => panic!("expected Cartesian, got {other:?}"),
        }
    }

    /// MarkBatch with many nodes (simulating a large dataset) must serialize
    /// and deserialize without truncation.
    #[test]
    fn mark_batch_large_node_count_survives_round_trip() {
        let nodes: Vec<SceneNode> = (0..1000)
            .map(|i| SceneNode::Circle {
                cx: i as f64 * 0.5,
                cy: (i as f64).powi(2) * 0.001,
                r: 3.0,
                style: default_fill_stroke(),
            })
            .collect();
        let batch = MarkBatch {
            kind: MarkBatchKind::Point,
            nodes,
            data_indices: Some((0..1000usize).collect()),
            tooltips: None,
            hrefs: None,
            descriptions: None,
            keys: None,
            blend: BlendMode::Normal,
            stroke_cap: None,
            stroke_join: None,
        };
        let json = serde_json::to_string(&batch).expect("serialize");
        let back: MarkBatch = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back.nodes.len(), 1000, "node count must survive round-trip");
    }

    /// Color::rgba must preserve all four channels exactly.
    #[test]
    fn color_rgba_channels_preserved() {
        let c = Color::rgba(10, 20, 30, 128);
        let json = serde_json::to_string(&c).unwrap();
        let back: Color = serde_json::from_str(&json).unwrap();
        assert_eq!(back.r, 10);
        assert_eq!(back.g, 20);
        assert_eq!(back.b, 30);
        assert_eq!(back.a, 128);
    }

    /// Color::rgb convenience constructor must set alpha to 255.
    #[test]
    fn color_rgb_alpha_is_255() {
        let c = Color::rgb(100, 150, 200);
        assert_eq!(c.a, 255, "Color::rgb alpha must be 255, got {}", c.a);
    }

    /// Opacity < 1.0 in FillStroke must survive round-trip without coercion.
    #[test]
    fn fillstroke_partial_opacity_round_trips() {
        let fs = FillStroke {
            fill: Some(Color::rgba(255, 0, 0, 200)),
            stroke: None,
            stroke_width: 1.5,
            opacity: 0.7,
            stroke_dash: Some(vec![4.0, 2.0]),
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        };
        let json = serde_json::to_string(&fs).expect("serialize");
        let back: FillStroke = serde_json::from_str(&json).expect("deserialize");
        assert!((back.opacity - 0.7).abs() < 1e-9, "opacity lost: {}", back.opacity);
        assert!((back.stroke_width - 1.5).abs() < 1e-12);
        let dash = back.stroke_dash.expect("dash must survive");
        assert_eq!(dash, vec![4.0, 2.0]);
    }
}
